#include <stdio.h>

static int multiply(int a, int b) { return a * b; }

int main(void) {
    printf("%d %d %d", multiply(2, 3), multiply(0, 5), multiply(-1, 4));
    return 0;
}

exercises.starter_code:
#include <stdio.h>

static int divide(int a, int b) { return 0; }

int main(void) {
    return 0;
}

exercises.solution:
#include <stdio.h>

static int divide(int a, int b) {
    if (b == 0) return -1;
    return a / b;
}

int main(void) {
    if (divide(10, 2) == 5 && divide(10, 0) == -1)
        printf("ok");
    return 0;
}

exercises.starter_code:
#include <stdio.h>
#include <string.h>

const char *validate(int age) { return ""; }

int main(void) { return 0; }

exercises.solution:
#include <stdio.h>
#include <string.h>

const char *validate(int age) {
    if (age < 0) return "age cannot be negative";
    return "ok";
}

int main(void) {
    const char *msg = validate(-5);
    printf(strstr(msg, "negative") ? "yes" : "no");
    return 0;
}

